CREATE TABLE `estudiantes` (
  `id_estudiante` int NOT NULL,
  `nombre` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `apellido_paterno` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `apellido_materno` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `grado` varchar(10) COLLATE utf8mb4_general_ci NOT NULL,
  `grupo` varchar(5) COLLATE utf8mb4_general_ci NOT NULL,
  `telefono_estudiante` varchar(15) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `telefono_padre` varchar(15) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id_estudiante`),
  UNIQUE KEY `idx_id_estudiante` (`id_estudiante`),
  KEY `idx_estudiantes_grado_grupo` (`grado`,`grupo`),
  KEY `idx_estudiantes_nombre` (`nombre`),
  KEY `idx_estudiantes_apellido_paterno` (`apellido_paterno`),
  KEY `idx_estudiantes_apellido_materno` (`apellido_materno`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
